  function setExpenseMonth(){const period=currentExpenseMonth();filters.expenseFrom=period.from;filters.expenseTo=period.to;}
  function expenseReportUrl(){const query=new URLSearchParams();if(filters.expenseFrom)query.set("from",filters.expenseFrom);if(filters.expenseTo)query.set("to",filters.expenseTo);return "/api/reports/expenses.pdf"+(query.size?"?"+query:"");}
  function expensePeriodLabel(){return filters.expenseFrom&&filters.expenseTo?`Du ${fmtDate(filters.expenseFrom)} au ${fmtDate(filters.expenseTo)} inclus`:filters.expenseFrom?`Depuis le ${fmtDate(filters.expenseFrom)}`:filters.expenseTo?`Jusqu’au ${fmtDate(filters.expenseTo)} inclus`:"Tout l’historique";}
  async function request(url,method="GET",body) {
    const controller=new AbortController(), timer=setTimeout(()=>controller.abort(),20000);
    try {
      const response=await fetch(url,{method,credentials:"same-origin",headers:{Accept:"application/json",...(body!==undefined?{"Content-Type":"application/json"}:{}),...(method!=="GET"?{"X-CSRF-Token":csrf}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{}),signal:controller.signal});
      const result=await response.json().catch(()=>({error:"Le serveur n’a pas retourné une réponse lisible."}));
      if(!response.ok){const error=Object.assign(new Error(result.error||"Cette opération n’a pas pu être terminée."),{status:response.status});if(response.status===401)location.assign("/connexion.html");throw error;}
      return result;
    } catch(error) { if(error.name==="AbortError")throw Object.assign(new Error("La réponse tarde à arriver. Le résultat doit être vérifié avant de recommencer."),{uncertain:true}); throw error; }
    finally {clearTimeout(timer);}
  }
  function setMenu(open) {document.body.classList.toggle("menu-open",open);$("mobile-menu").setAttribute("aria-expanded",String(open));$("mobile-backdrop").hidden=!open;}
