  function go(next) { if(!pages[next]||user.role!=="admin"&&["users","settings"].includes(next))return; if(logoSelecting||logoSaving||settingsSaving){toast("Attendez la fin de l’enregistrement des paramètres.");return;}if($("settings-form")&&formDirty&&!confirm("Quitter sans enregistrer ces paramètres ou ce logo ?"))return;settingsDirty=false;logoDraft=null;formDirty=false;page=next;history.replaceState(null,"","#"+page);setMenu(false);render();if(page==="users")loadUsers(); }
  function heading(title,description,action="") {return `<div class="page-heading"><div><p class="eyebrow">MON EXPLOITATION · ${escape(new Intl.DateTimeFormat("fr-FR",{day:"numeric",month:"long",year:"numeric",timeZone:state.settings.timezone||"Africa/Porto-Novo"}).format(new Date()).toUpperCase())}</p><h1 class="page-title">${escape(title)}</h1><p class="page-description">${escape(description)}</p></div>${action?`<div class="heading-actions">${action}</div>`:""}</div>`;}
