      `<div class="two-columns"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">L’inventaire par catégorie</h2><p class="panel-sub">Répartition des références actives</p></div><button class="panel-link" data-go="inventory">Tout l’inventaire →</button></div><div class="panel-content">${categories.map(category=>{const count=items.filter(i=>i.category===category).length;return `<div class="category-row"><span class="category-symbol">${icon(categoryIcon(category))}</span><div class="category-copy"><div class="category-line"><span>${escape(category)}</span><span>${count} article${count>1?"s":""}</span></div><div class="category-track"><div class="category-fill" style="width:${items.length?count/items.length*100:0}%"></div></div></div></div>`;}).join("")}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Derniers mouvements</h2><p class="panel-sub">Le fil de l’activité de la ferme</p></div><button class="panel-link" data-go="movements">Tout voir →</button></div>${state.movements.length?`<div class="panel-content">${state.movements.slice(0,4).map(m=>`<div class="activity-row"><span class="activity-icon ${escape(m.type)}">${icon(m.type==="entry"||m.type==="opening"?"plus":"movements")}</span><div class="activity-copy"><strong>${escape(m.itemName||state.items.find(i=>i.id===m.itemId)?.name||"Article")}</strong><p>${escape(movementLabels[m.type]||m.type)} · ${number(m.quantity)} ${escape(m.unit)} · ${escape(m.createdBy||"Équipe")}</p></div><span class="activity-time">${escape(fmtDate(m.date,true))}</span></div>`).join("")}</div>`:empty("L’activité commence ici","Les entrées, sorties et pertes apparaîtront ici dès leur enregistrement.","","movements")}</section></div>`+
      `<section class="panel stock-table"><div class="panel-head"><div><h2 class="panel-title">${alerts.length?"Les stocks à surveiller":"Votre inventaire partagé"}</h2><p class="panel-sub">${alerts.length?"Les articles au niveau ou en dessous du seuil défini":"Une vue commune pour toutes les personnes autorisées"}</p></div><button class="panel-link" data-go="inventory">Consulter l’inventaire →</button></div>${items.length?inventoryRows(alerts.length?alerts:items.slice(0,5),true):empty("Un inventaire encore vierge","Aucune donnée d’exemple : les chiffres affichés seront ceux de votre ferme.")}</section>`;
