  function usersPage(){return heading("Une équipe, des accès adaptés.","Le responsable attribue un compte personnel à chacun. La consultation à distance donne accès aux stocks et aux rapports, sans les modifier.",action("add-user","Créer un accès"))+`<section class="panel"><div class="table-wrap"><table class="data-table" id="users-table"><thead><tr><th>Compte</th><th>Rôle</th><th>État</th><th>Actions</th></tr></thead><tbody>${users.length?users.map(u=>`<tr><td><span class="user-name"><span class="avatar">${escape(u.username.slice(0,1).toUpperCase())}</span><span class="item-name">${escape(u.username)}${u.id===user.id?' <span class="item-meta">Votre compte</span>':""}</span></span></td><td>${escape(roles[u.role]||u.role)}</td><td><span class="badge ${u.enabled?"green":"muted"}">${u.enabled?"Actif":"Désactivé"}</span>${u.mustChangePassword?'<span class="item-meta">Mot de passe initial à changer</span>':""}</td><td>${u.id!==user.id?`<div class="row-actions"><button class="button secondary small" data-user-toggle="${escape(u.id)}" type="button">${u.enabled?"Désactiver":"Réactiver"}</button><button class="button ghost small" data-user-reset="${escape(u.id)}" type="button">Réinitialiser le mot de passe</button></div>`:'<span class="item-meta">Compte connecté</span>'}</td></tr>`).join(""):'<tr><td colspan="4"><span class="helper">Chargement des accès…</span></td></tr>'}</tbody></table></div><div class="security-note">${icon("shield")}<span>Chacun utilise son propre mot de passe. Les nouveaux comptes doivent le changer à leur première connexion. Une désactivation ou une réinitialisation ferme leurs sessions.</span></div></section>`;}
