      $("expense-all").onclick=()=>{filters.expenseFrom=filters.expenseTo="";expenseNotice="";formDirty=false;render();};$("expense-month").onclick=()=>{setExpenseMonth();expenseNotice="";formDirty=false;render();};if($("expense-show-all"))$("expense-show-all").onclick=$("expense-all").onclick;
