  function loadState(quiet=false) {
    if(stateRead) {
      if(quiet)return stateRead;
      // A confirmed write needs a new snapshot, even when a refresh that
      // started before the write is still in flight. Coalesce queued reads.
      if(!stateReload)stateReload=stateRead.then(()=>{stateReload=null;return loadState(false);});
      return stateReload;
    }
    $("refresh").disabled=true;
    const read=(async()=>{
      try {
        const latest=await request("/api/state");
        // A later explicit refresh supersedes this response. It must not
        // replace a new lot or a submitted form with an older snapshot.
        if(stateReload)return;
        state=latest;state.items||=[];state.movements||=[];state.expenses||=[];state.goliathBatches||=[];state.goliathEvents||=[];state.notes||=[];state.settings||={};
        if(!expensePeriodReady){setExpenseMonth();expensePeriodReady=true;}
        if(!formDirty&&!$("editor").open&&!$("password-dialog").open)render();
      }catch(error){
        if(stateReload)return;
        if(!quiet)toast(error.message);
        if(!state.updatedAt&&!state.items.length)$("workspace").innerHTML=heading("Les données sont momentanément indisponibles.","Votre inventaire reste sur le serveur. Utilisez Actualiser pour réessayer.")+`<div class="notice error">${escape(error.message)}</div>`;
      }
    })();
    stateRead=read.finally(()=>{stateRead=null;if(!stateReload)$("refresh").disabled=false;});
    return stateRead;
  }

  async function loadUsers(){try{const result=await request("/api/users");users=result.users||[];if(page==="users")render();}catch(error){toast(error.message);}}
  function editorError(message){$("editor-error").textContent=message;$("editor-error").hidden=!message;}
  function setEditorBusy(busy,lock=false){modalBusy=busy;$("editor-submit").disabled=busy;$("editor-close").disabled=busy;$("editor-cancel").disabled=busy;$("editor-form").querySelectorAll("#editor-fields input,#editor-fields select,#editor-fields textarea").forEach(el=>{if(!el.dataset.fixedDisabled)el.disabled=busy||lock;});$("editor-submit").textContent=busy?"Enregistrement…":lock?"Vérifier et réessayer":editor?.submit||"Enregistrer";}
  function openEditor(config){
    if(pendingIntent&&!config.resume){resumeIntent();return;}
    editor=config;formDirty=false;$("editor-title").textContent=config.title;$("editor-fields").innerHTML=config.fields;$("editor-submit").textContent=config.submit||"Enregistrer";editorError("");$("editor-form").querySelectorAll(":disabled").forEach(el=>el.dataset.fixedDisabled="true");
    $("editor-form").oninput=()=>formDirty=true;
    $("editor-form").onsubmit=async event=>{event.preventDefault();if(modalBusy||!$("editor-form").reportValidity())return;const data=Object.fromEntries(new FormData(event.target));let payload;try{payload=config.resume?pendingIntent.payload:config.payload(data);}catch(error){editorError(error.message);return;}setEditorBusy(true);editorError("");
    if(config.kind&&retryableKinds.includes(config.kind)){pendingIntent={kind:config.kind,payload,url:config.url,title:config.title};rememberIntent();}
    try{
      const result=await request(config.url,config.method||"POST",payload);
      if(config.kind&&retryableKinds.includes(config.kind)){pendingIntent=null;rememberIntent();}
      formDirty=false;$("editor").close();toast(config.success||"Enregistrement effectué.");if(config.after)await config.after(result);else await loadState();
    }catch(error){
      const uncertain=!error.status||error.status>=500||error.uncertain;
      if(config.kind&&retryableKinds.includes(config.kind)&&uncertain){pendingIntent={kind:config.kind,payload,url:config.url,title:config.title};rememberIntent();config.resume=true;editorError(error.message+" Le formulaire est conservé. Réessayez pour retrouver la même opération ; ne l’enregistrez pas une seconde fois.");}
      else{if(config.kind&&retryableKinds.includes(config.kind)){pendingIntent=null;rememberIntent();config.resume=false;}editorError(error.message+(error.status===409?" Actualisez les données puis vérifiez votre saisie.":""));}
    }finally{setEditorBusy(false,Boolean(config.resume&&pendingIntent));}
    };
    $("editor").showModal();if(config.resume){editorError("Cette opération attend sa confirmation. Les informations sont conservées ; le serveur reconnaîtra la même référence.");setEditorBusy(false,true);}
  }
  function closeEditor(){if(modalBusy)return;if(formDirty&&!pendingIntent&&!confirm("Fermer sans enregistrer cette saisie ?"))return;formDirty=false;$("editor").close();if(pendingIntent)render();}
